import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class OrderingRulesTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        Comparator<String> byLength = (a, b) -> Integer.compare(a.length(), b.length());
        Comparator<String> alphabetical = (a, b) -> a.compareTo(b);
        Comparator<String> lengthThenAlpha = OrderingRules.chain(List.of(byLength, alphabetical));

        List<String> words = List.of("pear", "fig", "kiwi", "date");
        checkCall("length then alphabetical", "[fig, date, kiwi, pear]",
                () -> OrderingRules.sortedCopy(words, lengthThenAlpha).toString());
        checkCall("alphabetical alone", "[date, fig, kiwi, pear]",
                () -> OrderingRules.sortedCopy(words, alphabetical).toString());
        checkCall("reversed(alphabetical)", "[pear, kiwi, fig, date]",
                () -> OrderingRules.sortedCopy(words, OrderingRules.reversed(alphabetical)).toString());
        checkCall("reversed(chain)", "[pear, kiwi, date, fig]",
                () -> OrderingRules.sortedCopy(words, OrderingRules.reversed(lengthThenAlpha)).toString());
        checkCall("an empty rule list leaves the order alone", "[pear, fig, kiwi, date]",
                () -> OrderingRules.sortedCopy(words, OrderingRules.chain(new ArrayList<Comparator<String>>())).toString());
        checkCall("the input list is not modified", "[pear, fig, kiwi, date]", () -> {
            OrderingRules.sortedCopy(words, alphabetical);
            return words.toString();
        });
        checkCall("chain stops at the first non-zero rule", 1, () -> {
            int[] asked = {0};
            Comparator<String> counting = (a, b) -> {
                asked[0]++;
                return 0;
            };
            OrderingRules.chain(List.of(byLength, counting)).compare("aa", "b");
            return asked[0] == 0 ? 1 : 0;
        });
        checkCall("numbers sort too", "[1, 2, 3]",
                () -> OrderingRules.sortedCopy(List.of(3, 1, 2), (a, b) -> Integer.compare(a, b)).toString());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

