import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class OrderingRules {

    public static <T> Comparator<T> chain(List<Comparator<T>> rules) {
        return (a, b) -> {
            for (Comparator<T> rule : rules) {
                int answer = rule.compare(a, b);
                if (answer != 0) {
                    return answer;
                }
            }
            return 0;
        };
    }

    public static <T> Comparator<T> reversed(Comparator<T> rule) {
        return (a, b) -> rule.compare(b, a);
    }

    public static <T> List<T> sortedCopy(List<T> items, Comparator<T> rule) {
        List<T> copy = new ArrayList<>(items);
        copy.sort(rule);
        return copy;
    }
}
